pub fn op_parser_sax_error(data: &[u8], iters: u64) -> String {
    let input_sum = checksum(data);
    let first_len = data.len().min(127);
    let msg = b"harness message\0";
    let pref = b"pfx\0";

    let mut digest = 0u64;
    let mut last_err = 0i32;

    for _ in 0..iters {
        unsafe {
            let first_ptr = if first_len == 0 {
                null()
            } else {
                data.as_ptr() as *const c_char
            };

            let ctxt = hp::htmlCreatePushParserCtxt(
                null_mut(),
                null_mut(),
                first_ptr,
                bounded_i32_len(first_len),
                null(),
                0 as hp::xmlCharEncoding,
            );

            let mut iter_digest = 0u64;
            iter_digest = fold(iter_digest, (!ctxt.is_null()) as u64);
            last_err = 0;

            if !ctxt.is_null() {
                iter_digest = fold(iter_digest, xsax::xmlSAX2GetLineNumber(ctxt as *mut c_void) as u32 as u64);
                iter_digest = fold(iter_digest, xsax::xmlSAX2GetColumnNumber(ctxt as *mut c_void) as u32 as u64);
                iter_digest = fold(iter_digest, xsax::xmlSAX2IsStandalone(ctxt as *mut c_void) as u32 as u64);
                iter_digest = fold(iter_digest, xsax::xmlSAX2HasInternalSubset(ctxt as *mut c_void) as u32 as u64);
                iter_digest = fold(iter_digest, xsax::xmlSAX2HasExternalSubset(ctxt as *mut c_void) as u32 as u64);

                let pid = xsax::xmlSAX2GetPublicId(ctxt as *mut c_void);
                let sid = xsax::xmlSAX2GetSystemId(ctxt as *mut c_void);
                let (_, ps) = c_xml_len_and_checksum(pid as *const u8);
                let (_, ss) = c_xml_len_and_checksum(sid as *const u8);
                iter_digest = fold(iter_digest, ps);
                iter_digest = fold(iter_digest, ss);

                xsax::xmlSAX2InternalSubset(ctxt as *mut c_void, b"html\0".as_ptr(), null(), null());
                xsax::xmlSAX2ExternalSubset(ctxt as *mut c_void, b"html\0".as_ptr(), null(), null());
                let ri = xsax::xmlSAX2ResolveEntity(ctxt as *mut c_void, null(), null());
                let ge = xsax::xmlSAX2GetEntity(ctxt as *mut c_void, b"amp\0".as_ptr());
                iter_digest = fold(iter_digest, (!ri.is_null()) as u64);
                iter_digest = fold(iter_digest, (!ge.is_null()) as u64);

                let lkup = xp::xmlParserNsLookupSax(ctxt as *mut _, pref.as_ptr());
                let upd = xp::xmlParserNsUpdateSax(ctxt as *mut _, pref.as_ptr(), null_mut());
                iter_digest = fold(iter_digest, (!lkup.is_null()) as u64);
                iter_digest = fold(iter_digest, upd as u32 as u64);

                let np = xp::nodePush(ctxt as *mut _, null_mut());
                let po = xp::nodePop(ctxt as *mut _);
                iter_digest = fold(iter_digest, np as u32 as u64);
                iter_digest = fold(iter_digest, (!po.is_null()) as u64);

                let ip = xp::inputPush(ctxt as *mut _, null_mut());
                let io = xp::inputPop(ctxt as *mut _);
                iter_digest = fold(iter_digest, ip as u32 as u64);
                iter_digest = fold(iter_digest, (!io.is_null()) as u64);

                let wr = xp::xmlWarningMsg(
                    ctxt as *mut _,
                    0 as xp::xmlParserErrors,
                    b"warn\0".as_ptr() as *const c_char,
                    null(),
                    null(),
                );
                iter_digest = fold(iter_digest, wr as u32 as u64);

                let mut handler = None;
                xe::initGenericErrorDefaultFunc(&mut handler);
                xe::xmlSetGenericErrorFunc(null_mut(), handler);
                xe::xmlSetStructuredErrorFunc(null_mut(), None);
                xe::xmlGenericErrorDefaultFunc(null_mut(), msg.as_ptr() as *const c_char);

                xe::xmlParserError(ctxt as *mut c_void, msg.as_ptr() as *const c_char);
                xe::xmlParserWarning(ctxt as *mut c_void, msg.as_ptr() as *const c_char);
                xe::xmlParserValidityError(ctxt as *mut c_void, msg.as_ptr() as *const c_char);

                xpi::xmlErrMemory(ctxt as *mut _, msg.as_ptr() as *const c_char);
                xpi::__xmlErrEncoding(
                    ctxt as *mut _,
                    0 as xpi::xmlParserErrors,
                    msg.as_ptr() as *const c_char,
                    null(),
                    null(),
                );
                xpi::xmlFatalErr(ctxt as *mut _, 0 as xpi::xmlParserErrors, msg.as_ptr() as *const c_char);
                iter_digest = fold(iter_digest, xpi::xmlParserGrow(ctxt as *mut _) as u32 as u64);
                xpi::xmlParserShrink(ctxt as *mut _);
                xpi::xmlHaltParser(ctxt as *mut _);

                if first_len < data.len() {
                    let rc = hp::htmlParseChunk(
                        ctxt,
                        data[first_len..].as_ptr() as *const c_char,
                        bounded_i32_len(data.len() - first_len),
                        0,
                    );
                    iter_digest = fold(iter_digest, rc as u32 as u64);
                }
                let rc2 = hp::htmlParseChunk(ctxt, null(), 0, 1);
                iter_digest = fold(iter_digest, rc2 as u32 as u64);

                let bc = enc::xmlByteConsumed(ctxt.cast()) as i64;
                iter_digest = fold(iter_digest, bc as u64);

                let errp = xe::xmlCtxtGetLastError(ctxt.cast());
                last_err = if errp.is_null() { 0 } else { (*errp).code };
                iter_digest = fold(iter_digest, last_err as u32 as u64);

                hp::htmlFreeParserCtxt(ctxt);
            }

            iter_digest = fold(iter_digest, input_sum);
            digest = fold(digest, iter_digest);
        }
    }

    format!("op=parser_sax_error err={} digest={:016x}", last_err, digest)
}

